"""Native fixed component parent plus its installation-relative loader.

The actual child artifact identity is a separate fixed HIA catalog role inside
the loader capsule. This packer accepts only the two bounded native bodies.
"""
from pathlib import Path
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_artifact_publication import document
from tools import generate_hia_clang_value_packer as base
from tools import generate_hia_native_fixed_component_packer as loader
ROOT=Path(__file__).resolve().parents[1]
BRIDGE=bytes.fromhex('')
ROLES=('component','loader')
MAGIC=int.from_bytes(b'HIAGPBP1','little')
FIXUPS=(('component',882),('loader',1187))
ENTRY_OFFSETS={}
LENGTH_FIXUPS=()
DYNAMIC_RELOCATIONS=tuple(('loader',at,name)for at,name in loader.RELOCATIONS)
IMPORTS=loader.IMPORTS
EXPORT='hia_generation_lease_owner_component'
EXPORT_SIZE=1444
BRIDGE_EXPORTS={'@bind':[8,1893],'@bind_owner':[1444,457],'@exception':[21,1880],'@prepare':[13,1888]}
EXTRA_EXPORTS=(
 ('hia_generation_lease_owner_component_bind','@bind'),
 ('hia_generation_lease_owner_component_prepare','@prepare'),
 ('hia_generation_lease_owner_component_exception','@exception'),
 ('hia_generation_lease_owner_component_bind_owner','@bind_owner'),
)
def call(fn,*args):
    changes={n:globals()[n]for n in ('ROLES','MAGIC','BRIDGE','FIXUPS','ENTRY_OFFSETS','LENGTH_FIXUPS',
      'DYNAMIC_RELOCATIONS','IMPORTS','EXPORT','EXPORT_SIZE','EXTRA_EXPORTS','BRIDGE_EXPORTS')}
    saved={n:getattr(base,n)for n in changes}
    try:
        for n,v in changes.items():setattr(base,n,v)
        return fn(*args)
    finally:
        for n,v in saved.items():setattr(base,n,v)
def source_program():return call(base.source_program)
def reference_object(parts):return call(base.reference_object,parts)
def reference_flat(parts):return call(base.reference_flat,parts)
def main():
    tree=document(source_program(),'generation_lease_owner_component_packer')
    path=ROOT/'examples/hia_bootstrap/generation_lease_owner_component_packer.hepta'
    path.write_text(render_assembly(tree))
    print(path.name,path.stat().st_size,len(tree['functions']),
      sum(len(f['blocks'])for f in tree['functions']),flush=True)
if __name__=='__main__':main()
